class ScreenWakeLocker{_onVisibilityChange(){if(!this.wakeLockSentinel){return}if(document.visibilityState==="visible"){this.lock().catch(console.error);}}requestWakeLock(){if(!navigator.wakeLock){return Promise.reject()}if(this.wakeLockSentinel){return Promise.resolve()}return navigator.wakeLock.request("screen").then(e=>{this.wakeLockSentinel=e;})}isLocked(){if(!this.wakeLockSentinel){return false}return !this.wakeLockSentinel.released}lock(){return this.requestWakeLock().then(()=>{if(this.wakeLockSentinel){document.addEventListener("visibilitychange",this.onVisibilityChange);}})}unlock(){if(!this.wakeLockSentinel){return Promise.resolve()}document.removeEventListener("visibilitychange",this.onVisibilityChange);return this.wakeLockSentinel.release().finally(()=>{this.wakeLockSentinel=null;})}constructor(){this.onVisibilityChange=this._onVisibilityChange.bind(this);}}

export { ScreenWakeLocker };
